UPDATE TB_VIDEO_CONF
SET ROOM_NM = #{roomNm}
WHERE VCONF_ID = #{vconfId}

UPDATE TB_VIDEO_CONF
SET CONF_STTUS_CD = #{confSttusCd}
WHERE VCONF_ID = #{vconfId}

UPDATE TB_VIDEO_PTCPT
SET JOIN_DT = SYSDATE
WHERE VCONF_PTCPT_ID = #{vconfPtcptId}

UPDATE TB_VIDEO_MOM
SET MOM_CN       = #{momCn},
    MOM_STTUS_CD = #{momSttusCd},
    EDTR_ID      = #{edtrId}
WHERE MOM_ID = #{momId}
